CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.owner_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), email text NOT NULL);
GRANT ALL ON public.owner_settings TO service_role;
ALTER TABLE public.owner_settings ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.assign_owner_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.owner_settings WHERE lower(email)=lower(NEW.email)) THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER on_owner_confirmed AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_owner_role();
CREATE TABLE public.services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 100), description text NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 1000), icon text NOT NULL DEFAULT 'Monitor' CHECK(icon IN ('Monitor','Play','Shield','Globe','FileText','Download')), active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.services TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.services TO authenticated;
GRANT ALL ON public.services TO service_role;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_services ON public.services FOR SELECT TO anon,authenticated USING(active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY manage_services ON public.services FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.customer_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), email text NOT NULL CHECK(length(email)<=255 AND email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'), phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30), service text NOT NULL CHECK(length(service) BETWEEN 1 AND 100), message text NOT NULL CHECK(length(trim(message)) BETWEEN 1 AND 2000), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','in_progress','resolved')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.customer_requests TO authenticated;
GRANT ALL ON public.customer_requests TO service_role;
ALTER TABLE public.customer_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_requests ON public.customer_requests FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.submit_request(_name text,_email text,_phone text,_service text,_message text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtext(lower(trim(_email)))); IF EXISTS(SELECT 1 FROM public.customer_requests WHERE lower(email)=lower(trim(_email)) AND created_at>now()-interval '1 minute') THEN RAISE EXCEPTION 'Please wait a minute before sending another request.'; END IF; INSERT INTO public.customer_requests(name,email,phone,service,message) VALUES(trim(_name),lower(trim(_email)),trim(_phone),_service,trim(_message)); END $$;
REVOKE ALL ON FUNCTION public.submit_request(text,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_request(text,text,text,text,text) TO anon,authenticated;
CREATE TABLE public.visits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visitor_id uuid NOT NULL, visit_date date NOT NULL DEFAULT current_date, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(visitor_id,visit_date));
GRANT SELECT ON public.visits TO authenticated;
GRANT ALL ON public.visits TO service_role;
ALTER TABLE public.visits ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_visits ON public.visits FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.record_visit(_visitor_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO public.visits(visitor_id) VALUES(_visitor_id) ON CONFLICT(visitor_id,visit_date) DO NOTHING $$;
REVOKE ALL ON FUNCTION public.record_visit(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_visit(uuid) TO anon,authenticated;
CREATE INDEX requests_created ON public.customer_requests(created_at DESC);
CREATE INDEX visits_date ON public.visits(visit_date);